using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.LadysMantle;

/// <summary>
/// Lady's mantle, a rosette of round, pleated leaves that hold dew, in the Mistlands. Model: generated by
/// AssetSource/Tools/make_forage_models.py. Magecaps picked in the Mistlands can also give it.
/// </summary>
public class LadysMantle : ForageableBase
{
    /// <summary>
    /// Prefab name of the lady's mantle item.
    /// </summary>
    public const string PrefabName = "WhiteHiltLadysMantle";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Lady's Mantle";

    /// <inheritdoc/>
    protected override string Description => "Round, pleated leaves that hold a pearl of dew in every fold. Healers gathered the dew for their brews, and the leaves steep into a broth that wakes the eitr.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Thistle";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Dandelion";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.Mistlands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 2,
        ForcePlacement = true,
        GroupSizeMin = 2,
        GroupSizeMax = 5,
        GroupRadius = 3f,
        MinAltitude = 1f,
        MaxTilt = 30f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => "Pickable_Mushroom_Magecap";

    /// <inheritdoc/>
    protected override float ExtraDropChance => 0.2f;

    /// <inheritdoc/>
    protected override float DefaultGroundClearance => 0.1f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, "ladysmantle", 0.3f);
    }
}
